}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: u32) -> f64 {
    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let mean = mean_residual.max(0.0);
    let new_bin = bin_residual == bin_capacity;

    let progress = if total_items == 0 {
        1.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };
    let tail = 1.0 - progress;

    let fitting = fitting_bins_count as f64;
    let scarcity = if open_bins_count == 0 {
        1.0
    } else {
        (fitting / open_bins_count as f64).clamp(0.0, 1.0)
    };

    let item_ratio = (item / capacity).clamp(0.0, 1.0);
    let post_ratio = (post / capacity).clamp(0.0, 1.0);
    let mean_ratio = (mean / capacity).clamp(0.0, 1.0);
    let next = next_item_size as f64;
    let next_ratio = (next / capacity).clamp(0.0, 1.0);
    let consume_ratio = (item / residual.max(1.0)).clamp(0.0, 1.0);
    let next_slack = (post - next).max(0.0);

    let residual_gap = (post - mean).abs();
    let waste_above_mean = (post_ratio - mean_ratio).max(0.0);
    let below_mean = (mean_ratio - post_ratio).max(0.0);
    let fragmentation = if post > 0.0 {
        (post / item).min(1.0)
    } else {
        0.0
    };

    if new_bin {
        let alternatives = if fitting_bins_count == 0 {
            16.0
        } else {
            let concentration = 1.0 - scarcity;
            let residue_bonus = 5.2 * concentration;
            let urgency = if fitting_bins_count <= 2 { 4.0 } else { 0.0 };
            residue_bonus + urgency
        };

        let item_above_mean = (item - mean).max(0.0);
        let preserve_small_bins = if item_ratio < 0.22 {
            3.2 * (0.22 - item_ratio) / 0.22 * scarcity
        } else {
            0.0
        };
        let next_pressure = if next > item {
            1.8 * (next - item) / capacity * tail
        } else {
            0.0
        };
        let future_space = if next > post {
            0.12 * (next - post) * tail
        } else {
            0.0
        };

        alternatives
            + 1.7 * item_above_mean
            + preserve_small_bins
            + next_pressure
            + future_space
            - 1.2 * item_ratio
    } else {
        let fill = -3.1 * consume_ratio;
        let residue_cost = 8.4 * waste_above_mean + 0.18 * post / capacity;
        let mean_reward = -3.4 * below_mean * (0.35 + 0.65 * scarcity);

        let scarce_bonus = if fitting_bins_count == 1 {
            -10.0 - 0.22 * next
        } else if fitting_bins_count <= 3 {
            -2.7 * scarcity
        } else {
            0.0
        };

        let exact_close = if post == 0.0 {
            -9.5
        } else if post_ratio < 0.08 {
            -6.2 * (1.0 - post_ratio / 0.08)
        } else if post <= item / 2.0 {
            -2.8
        } else {
            0.0
        };

        let next_fit = if next > 0.0 && next <= post {
            let tightness = 1.0 - (next_slack / capacity).clamp(0.0, 1.0);
            let valuable_fit = if next_ratio > 0.45 { 1.25 } else { 0.0 };
            -3.6 * tightness * (0.5 + 0.5 * scarcity) - valuable_fit
        } else {
            0.0
        };

        let next_miss = if next > post {
            0.065 * (next - post) * (0.3 + 0.7 * tail)
        } else {
            0.0
        };

        let awkward_space = if post_ratio > 0.18 && post_ratio < 0.42 {
            2.1 * (post_ratio - 0.18) / 0.24
        } else {
            0.0
        };

        let tiny_item_room = if item_ratio < 0.16 && post_ratio > 0.28 {
            1.8 * (post_ratio - 0.28)
        } else {
            0.0
        };

        let last_rescue = if fitting_bins_count == 1 && post < next {
            -4.0 * (1.0 - scarcity)
        } else {
            0.0
        };

        let early_waste = 1.1 * tail * waste_above_mean;
        let late_compaction = -1.6 * tail * below_mean;

        fill
            + residue_cost
            + mean_reward
            + scarce_bonus
            + exact_close
            + next_fit
            + next_miss
            + awkward_space
            + tiny_item_room
            + last_rescue
            + early_waste
            + late_compaction
            - 0.9 * fragmentation
    }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;
    let residual = bin_residual.min(bin_capacity) as f64;
    let after = post_residual.min(bin_capacity) as f64;
    let mean = mean_residual.max(0.0).min(capacity);
    let progress = if total_items > 0 {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    } else {
        1.0
    };
    let new_bin = bin_residual == bin_capacity;
    let fit_share = if open_bins_count > 0 {
        (fitting_bins_count as f64 / open_bins_count as f64).clamp(0.0, 1.0)
    } else {
        1.0
    };

    let before_fill = (capacity - residual) / capacity;
    let after_fill = (capacity - after) / capacity;
    let after_ratio = after / capacity;
    let item_ratio = (item / capacity).min(1.0);
    let next_ratio = (next / capacity).min(1.0);
    let mean_ratio = mean / capacity;
    let next_fits = next <= after;
    let next_dead = after > 0.0 && after < next;
    let residue_dead = after > 0.0 && after < item.min(next);
    let scarcity = 1.0 - fit_share;
    let horizon = 1.0 - progress;

    let mut score = 0.0;

    if new_bin {
        score += 25.0 * scarcity;
        score += 8.0 * horizon;
        score += 13.0 * (1.0 - item_ratio);
        score += 0.20 * (item - mean).max(0.0);

        if next_fits {
            score -= 8.0 * horizon;
        } else {
            score += 3.0 * next_ratio * horizon;
        }

        if fitting_bins_count > 0 && item <= mean {
            score += 5.0 * fit_share;
        }
        if fitting_bins_count == 1 {
            score += 2.5 * (mean - after).abs() / capacity;
        }
    } else {
        score -= 12.0 * before_fill;
        score -= 7.5 * after_fill;
        score -= 6.5 * after_ratio * after_ratio;

        if after == 0.0 {
            score -= 22.0;
        }
        if next_fits {
            score -= 8.0 * next_ratio;
        } else {
            score += 4.0 * next_ratio * horizon;
        }

        score -= 9.0 * residue_dead as u8 as f64 * (0.35 + 0.65 * horizon);
        if residue_dead {
            score += 12.0 + 0.35 * after;
            score += 6.0 * (item.min(next) - after) / capacity;
        }

        let exact = (after - item).abs();
        score -= 3.8 * (exact / capacity).min(1.0);
        score -= 3.0 * (after_ratio - mean_ratio).abs();

        if next_dead {
            score += 3.2 * (next - after) / capacity * horizon;
        }
    }

    if !new_bin && fitting_bins_count == 1 {
        score -= 24.0 - 0.30 * next;
        if next_dead {
            score -= 4.5 * (next - after) / capacity;
        }
        if after >= next && after - next < capacity * 0.12 {
            score -= 4.5;
        }
    } else if !new_bin && fitting_bins_count == 2 {
        score -= 6.0 * horizon;
        if after >= next && after - next < capacity * 0.15 {
            score -= 4.5;
        }
    } else if !new_bin && fitting_bins_count > 2 {
        score -= 1.7 * fit_share * horizon;
    }

    let residual_excess = (after - mean).max(0.0);
    score -= 2.8 * (residual_excess / capacity).min(1.0);
    score += 1.1 * horizon * (mean - after).abs() / capacity;

    let dead_fraction = if capacity > 0.0 {
        ((mean - after).max(0.0) / capacity).min(1.0)
    } else {
        0.0
    };
    let fragmented = after > 0.0
        && after < item
        && after < next
        && after < capacity * 0.25;
    if !new_bin && fragmented {
        score += 3.5 * dead_fraction * (0.4 + 0.6 * scarcity);
    }

    if !new_bin {
        let residual_slack = (after - item).max(0.0);
        let useful_slack = residual_slack.min(next);
        score -= 2.0 * (useful_slack / capacity).min(1.0);
        if after > item && after < item + capacity * 0.08 {
            score -= 2.4 * horizon;
        }
    }

    let small_residue = after > 0.0 && after <= capacity * 0.15;
    if !new_bin && small_residue {
        let gap = (item.min(next) - after).max(0.0) / capacity;
        score += 4.0 * gap * (0.3 + 0.7 * scarcity);
    }

    let residue_dispersion = (after_ratio - mean_ratio).abs();
    if !new_bin && residue_dispersion > 0.18 {
        score += 2.5 * (residue_dispersion - 0.18) * (0.5 + 0.5 * scarcity);
    }

    let target_gap = (after - next).abs() / capacity;
    if !new_bin && target_gap <= 0.10 {
        score -= 4.0 * (1.0 - target_gap / 0.10) * (0.35 + 0.65 * horizon);
    }

    let residual_square = after_ratio * after_ratio;
    let dead_pressure = if after < next {
        ((next - after) / capacity).min(1.0)
    } else {
        0.0
    };
    if !new_bin {
        score -= 2.0 * residual_square * (0.4 + 0.6 * scarcity);
        score += 5.0 * dead_pressure * (0.25 + 0.75 * scarcity) * horizon;
    }

    let near_mean = (after_ratio - mean_ratio).abs() < 0.12;
    if !new_bin && near_mean && after > 0.0 && after < item.min(next) {
        score += 3.0 * scarcity;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: u32) -> f64 {
    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let mean = mean_residual.max(0.0);

    let progress = if total_items == 0 {
        1.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };
    let tail = 1.0 - progress;
    let new_bin = bin_residual == bin_capacity;

    let item_ratio = (item / capacity).clamp(0.0, 1.0);
    let residual_ratio = (residual / capacity).clamp(0.0, 1.0);
    let post_ratio = (post / capacity).clamp(0.0, 1.0);
    let next_ratio = (next / capacity).clamp(0.0, 1.0);

    let before_fill = (1.0 - residual_ratio).clamp(0.0, 1.0);
    let after_fill = (1.0 - post_ratio).clamp(0.0, 1.0);
    let occupancy_gain = (after_fill - before_fill).clamp(0.0, 1.0);

    // Fragmentation: small leftover fragments are costly when many bins remain open.
    let fragment = post_ratio
        * (1.0 - (post / item.max(1.0)).min(1.0))
        * (0.35 + 0.65 * tail);
    let large_hole = (post_ratio - 0.5).max(0.0);
    let hole_cost = 8.0 * large_hole * large_hole;

    // A bin is attractive when the item removes a substantial part of its hole.
    let utilization_gain = 7.0 * occupancy_gain
        + 5.0 * (item / residual.max(1.0)).min(1.0) * (1.0 - post_ratio);
    let waste_cost = 10.0 * (1.0 - post_ratio).powi(2)
        + 3.0 * ((post - item).max(0.0) / capacity);

    // Keep residuals near the population mean, but reward an exact finish.
    let mean_gap = (mean - post).abs();
    let mean_gap_ratio = (mean_gap / capacity).clamp(0.0, 1.0);
    let dispersion_cost = 1.7 * mean_gap_ratio * (1.0 + 0.5 * tail);

    let scarcity = if open_bins_count == 0 {
        1.0
    } else {
        (fitting_bins_count as f64 / open_bins_count as f64).clamp(0.0, 1.0)
    };

    let next_fits = if post >= next && next > 0.0 {
        (post / next).floor()
    } else {
        0.0
    };

    if new_bin {
        // Opening is justified mainly by avoiding a fragmented placement or by
        // having no viable alternatives.
        let fragmented_alternative = if fitting_bins_count > 0 {
            let close_after = (post / capacity).min(0.22);
            let unusable = close_after * (1.0 - (post / item.max(1.0)).min(1.0));
            let poor_competition = 1.0 - scarcity;
            13.0 * unusable + 8.0 * poor_competition
        } else {
            9.0
        };

        let carry_cost = 5.0 * tail
            + 7.0 * scarcity
            + 5.0 * (1.0 - item_ratio)
            + 2.2 * (mean - item).max(0.0) / capacity
            + 2.5 * tail * (next / capacity);

        let reuse_value = if fitting_bins_count > 0 {
            7.0 * scarcity
                + 2.5 * (1.0 - post_ratio)
                - 3.0 * (post / capacity).min(0.15)
                - 0.8 * next_fits * tail
        } else {
            -8.0
        };

        carry_cost + fragmented_alternative - reuse_value
    } else {
        // Exact completion dominates ordinary density.
        let exact_bonus = if post == 0.0 {
            -11.0 - 2.0 * tail
        } else {
            let tiny = (post / (0.08 * capacity)).min(1.0);
            -4.0 * tiny * tiny
        };

        // Examine whether the next item will fit, and how well this choice
        // prepares the bin for it.
        let next_pressure = if next > post {
            let deficit_ratio = ((next - post) / next.max(1.0)).clamp(0.0, 1.0);
            8.0 * deficit_ratio * (0.45 + 0.55 * tail)
                + 0.035 * (next - post)
        } else {
            let after_next = post - next;
            let residue_ratio = (after_next / capacity).clamp(0.0, 1.0);
            let useful = 1.0 - (after_next / next.max(1.0)).min(1.0);
            -2.3 * useful * (1.0 - residue_ratio) * tail
        };

        // If this placement strands the only viable bin, opening is preferable.
        let trap = if fitting_bins_count == 1 && post < next {
            7.0 * (1.0 - scarcity) + 0.045 * (next - post)
        } else {
            0.0
        };

        // Few fitting bins create competition; abundant alternatives relax it.
        let competition = if fitting_bins_count == 1 {
            -9.0 - 0.25 * next
        } else if fitting_bins_count <= 3 {
            -3.0 * scarcity
        } else {
            0.0
        };

        // Prefer the tightest residual among comparable choices, while allowing
        // a modest look-ahead bonus for retaining room for the next item.
        let tight_remaining = 1.0 - (post / residual.max(1.0)).min(1.0);
        let residual_value = -2.8 * tight_remaining
            + 0.10 * post
            - 0.10 * (post - next).max(0.0);

        utilization_gain
            + waste_cost
            - hole_cost
            - fragment * 5.0
            - dispersion_cost
            + exact_bonus
            + next_pressure
            + trap
            + competition
            + residual_value
            + 1.1 * tail * (mean_gap / capacity)
    }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: u32) -> f64 {
    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let mean = mean_residual.max(0.0);
    let new_bin = bin_residual == bin_capacity;
    let next = next_item_size as f64;
    let progress = if total_items == 0 {
        1.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };
    let tail = 1.0 - progress;
    let scarcity = if open_bins_count == 0 {
        1.0
    } else {
        (fitting_bins_count as f64 / open_bins_count as f64).clamp(0.0, 1.0)
    };
    let item_ratio = (item / capacity).clamp(0.0, 1.0);
    let post_ratio = (post / capacity).clamp(0.0, 1.0);
    let fit_gap = (post - item).max(0.0);
    let dead_fraction = (post / capacity).clamp(0.0, 1.0);
    let near_full = 1.0 - dead_fraction;
    let mean_gap = (mean - post).abs();
    let next_ratio = (next / capacity).clamp(0.0, 1.0);

    if new_bin {
        let empty_pressure = 18.0 * tail
            + 9.0 * scarcity
            + 5.0 * (next_ratio - mean / capacity).max(0.0)
            - 0.12 * (item - mean).max(0.0);

        let reuse_value = if fitting_bins_count > 0 {
            11.0 * scarcity
                + 4.0 * (1.0 - scarcity)
                - 0.18 * (post - item).max(0.0)
                - 0.035 * (post / capacity).max(0.0)
        } else {
            -7.0
        };

        empty_pressure - reuse_value
    } else {
        let dead_space_penalty = 14.0 * dead_fraction
            + 0.32 * post
            + 0.0015 * post * post / capacity;

        let residual_flexibility = 0.16 * fit_gap
            + 0.10 * (post - next).max(0.0)
            - 0.11 * near_full * fit_gap;

        let scarcity_bonus = if fitting_bins_count == 1 {
            -18.0 - 0.40 * next
        } else if fitting_bins_count <= 3 {
            -4.2 * scarcity
        } else {
            0.0
        };

        let close_bonus = if post == 0 {
            -10.0
        } else if post <= item / 3.0 {
            -3.4
        } else {
            0.0
        };

        let lookahead_penalty = if next > post {
            0.085 * (next - post) * (0.45 + 0.55 * tail)
        } else {
            0.0
        };

        let future_fit_bonus = if post >= next && next > 0.0 {
            -0.055 * next * (0.5 + 0.5 * tail)
        } else {
            0.0
        };

        let emergency = if fitting_bins_count == 1 && post < next {
            -6.0 * (1.0 - scarcity)
        } else {
            0.0
        };

        dead_space_penalty
            + residual_flexibility
            + scarcity_bonus
            + close_bonus
            + lookahead_penalty
            + future_fit_bonus
            + emergency
            + 1.7 * tail * mean_gap
            - 0.035 * item_ratio * near_full
    }
}
